import{_ as a,o as e,c as s,a0 as t}from"./chunks/framework.tsJrOMu2.js";const k=JSON.parse('{"title":"添加上下文","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guides/add-context.md","filePath":"zh/guides/add-context.md"}'),l={name:"zh/guides/add-context.md"};function n(r,i,o,h,p,d){return e(),s("div",null,[...i[0]||(i[0]=[t('<h1 id="添加上下文" tabindex="-1">添加上下文 <a class="header-anchor" href="#添加上下文" aria-label="Permalink to &quot;添加上下文&quot;">​</a></h1><p><code>ContextProvider</code> 是向托管请求注入运行期上下文的主要方式。若需要改写已有历史，而不是仅仅在前面补消息，应使用 Transform Context，而不是把这类逻辑硬塞进 <code>Context Provider</code>。</p><h2 id="适用时机" tabindex="-1">适用时机 <a class="header-anchor" href="#适用时机" aria-label="Permalink to &quot;适用时机&quot;">​</a></h2><p>建议在读完以下内容后阅读本页：</p><ul><li><a href="./quickstart">快速开始</a></li><li><a href="./build-a-profile">构建 Profile</a></li><li><a href="./../concepts/context-and-compaction">上下文与压缩</a></li></ul><p>上下文机制主要用来回答以下问题：</p><ul><li>在运行期历史之前，应该额外放入哪些信息</li><li>Agent 在当前请求中应该看到哪些身份、租户或环境提示</li><li>哪些 memory、knowledge 或 workspace 摘要应在请求时可见</li></ul><p>如果说 <code>Profile</code> 定义的是 Agent「是谁」，那么 <code>Context Provider</code> 定义的就是 Agent「在请求时知道什么」。</p><h2 id="常见上下文输入" tabindex="-1">常见上下文输入 <a class="header-anchor" href="#常见上下文输入" aria-label="Permalink to &quot;常见上下文输入&quot;">​</a></h2><p>常见的上下文输入包括：</p><ul><li>用户身份</li><li>memory 摘要</li><li>knowledge 摘要</li><li>skills 摘要</li><li>workspace 快照</li><li>日期与运行期元数据</li></ul><p>这些信息通常会以合成的 user message 形式，插入到对话历史之前。</p><h2 id="两种主要方式" tabindex="-1">两种主要方式 <a class="header-anchor" href="#两种主要方式" aria-label="Permalink to &quot;两种主要方式&quot;">​</a></h2><h3 id="_1-直接添加-contextprovider" tabindex="-1">1. 直接添加 <code>ContextProvider</code> <a class="header-anchor" href="#_1-直接添加-contextprovider" aria-label="Permalink to &quot;1. 直接添加 `ContextProvider`&quot;">​</a></h3><p>当逻辑可以很直接地表达为「返回几条消息」时，优先使用 <code>Context Provider</code>：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { ContextProvider } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;@agentrail/app&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> identityProvider</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ContextProvider</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> async</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">context</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      role: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;user&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      content: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`Current tenant: ${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">context</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tenantId</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Current user: ${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">context</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">userId</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      timestamp: Date.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">now</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(),</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ];</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre></div><p>这是最直接、也最清晰的方式。</p><h3 id="_2-添加-transformcontextfn" tabindex="-1">2. 添加 <code>TransformContextFn</code> <a class="header-anchor" href="#_2-添加-transformcontextfn" aria-label="Permalink to &quot;2. 添加 `TransformContextFn`&quot;">​</a></h3><p>当需求不是「补充消息」，而是「改写已有消息数组」时，应使用 Transform Context：</p><ul><li>压缩过大的 <code>toolResult</code></li><li>对历史做脱敏或规范化</li><li>把多个请求期改写步骤串联起来</li></ul><p>可使用 <code>createTransformContext(...)</code> 将 Transform Context 与 <code>Context Provider</code> 组合到一起。<code>createContextProviderFromTransform(...)</code> 仍然存在，但它只是旧的 prepend-only 适配方式，不再是表达改写逻辑的推荐方式。</p><h2 id="推荐方式" tabindex="-1">推荐方式 <a class="header-anchor" href="#推荐方式" aria-label="Permalink to &quot;推荐方式&quot;">​</a></h2><p>如果 Host 采用默认 capability 模型，优先使用：</p><ul><li><code>createDefaultCapabilityContextProviders</code></li><li><code>createDefaultCapabilityTransformContext</code></li></ul><p>这种方式尤其适合组合以下内容：</p><ul><li>memory 索引摘要</li><li>knowledge 元数据摘要</li><li>skills 清单上下文</li><li>workspace 快照</li></ul><p>当前实现位于：</p><ul><li><a href="https://github.com/yai-dev/agentrail/blob/main/packages/capabilities/src/memory/context.ts" target="_blank" rel="noreferrer">packages/capabilities/src/memory/context.ts</a></li></ul><h2 id="仓库中的参考示例" tabindex="-1">仓库中的参考示例 <a class="header-anchor" href="#仓库中的参考示例" aria-label="Permalink to &quot;仓库中的参考示例&quot;">​</a></h2><p>playground 示例在这里组装请求上下文：</p><ul><li><a href="https://github.com/yai-dev/agentrail/blob/main/examples/playground-server/src/context/index.ts" target="_blank" rel="noreferrer">examples/playground-server/src/context/index.ts</a></li></ul><p>这个文件适合参考以下问题：</p><ul><li>如何把 Manager 单例放在 Route 文件之外</li><li>如何按请求构建 <code>Context Providers</code></li><li>如何把框架默认能力与示例应用自己的运行期接线组合起来</li></ul><h2 id="顺序很重要" tabindex="-1">顺序很重要 <a class="header-anchor" href="#顺序很重要" aria-label="Permalink to &quot;顺序很重要&quot;">​</a></h2><p><code>Context Providers</code> 并不是一组可随意交换顺序的辅助函数。顺序会影响模型最终看到的 prompt。</p><p>一般建议：</p><ul><li>身份、日期、环境头信息放在最前</li><li>memory 与 knowledge 摘要放在当前请求历史之前</li><li>workspace 快照放在足够靠后的位置，以反映最新状态</li></ul><p>如果 <code>Context Provider</code> 之间开始依赖复杂的隐式顺序，通常说明应该把它们重新分组或简化。</p><h2 id="适合放进-context-provider-的内容" tabindex="-1">适合放进 <code>Context Provider</code> 的内容 <a class="header-anchor" href="#适合放进-context-provider-的内容" aria-label="Permalink to &quot;适合放进 `Context Provider` 的内容&quot;">​</a></h2><p>适合的内容通常具备以下特点：</p><ul><li>体积紧凑</li><li>在单次请求中相对稳定</li><li>明确属于信息补充</li><li>可以安全地作为合成上下文插入</li></ul><p>不适合的内容包括：</p><ul><li>实际属于 <code>System Prompt</code> 的文本</li><li>route 专属的分支逻辑</li><li>大段原始文档，而不是摘要或索引</li></ul><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><p>避免以下做法：</p><ul><li>每次请求都注入过多原始状态</li><li>将 prompt 身份与请求期上下文混在一起</li><li>直接在 route handler 中拼接上下文</li><li>用 <code>Context Provider</code> 处理本应由工具负责的行为</li></ul><h2 id="更底层的-api" tabindex="-1">更底层的 API <a class="header-anchor" href="#更底层的-api" aria-label="Permalink to &quot;更底层的 API&quot;">​</a></h2><p>如果默认层过于固定，可以直接使用以下原语：</p><ul><li><code>ContextProvider</code></li><li><code>TransformContextFn</code></li><li><code>composeTransformContexts</code></li><li><code>createTransformContext</code></li><li><code>createContextProviderFromTransform</code></li></ul><p>这些能力位于 <code>@agentrail/app/advanced</code> 与 <code>@agentrail/capabilities</code> 中，可在不采用默认 capability 栈的前提下，自定义一条上下文处理管线。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./build-a-profile">构建 Profile</a></li><li><a href="./../reference/host-defaults">兼容 API</a></li><li><a href="./../reference/session-store">Session Store</a></li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>上下文管线就绪后，常见的下一步是扩展插件或管理 Prompt。可继续阅读 <a href="./write-a-plugin">编写插件</a> 或 <a href="./manage-prompts">管理 Prompt</a>。</p>',54)])])}const u=a(l,[["render",n]]);export{k as __pageData,u as default};
